  `middle_image` varchar(255) DEFAULT NULL,
  `middle_layout` enum('LEFT_IMAGE_RIGHT_TEXT','RIGHT_IMAGE_LEFT_TEXT','TEXT_ONLY') DEFAULT 'TEXT_ONLY',
  `conclusion_text` text,
  `conclusion_image` varchar(255) DEFAULT NULL,
  `conclusion_layout` enum('LEFT_IMAGE_RIGHT_TEXT','RIGHT_IMAGE_LEFT_TEXT','TEXT_ONLY') DEFAULT 'TEXT_ONLY',
