INSERT INTO `blog_posts` VALUES (2,'Azure Features','azure-features-360','Cloud','cloud','','','https://ik.imagekit.io/genospark/banner_CCeFojnlk.png','Azure mobile app\nStay connected to your Azure resources—anytime, anywhere. Now available for iOS and Android.\n','https://ik.imagekit.io/genospark/intro_image_yhyGYIHXs.jpg','RIGHT_IMAGE_LEFT_TEXT','View one portal, manage all your apps.\nView and manage all of your applications in one unified hub—including web apps, databases, virtual machines, virtual networks, storage, and Visual Studio team projects. Enjoy the flexibility of using the Azure portal\'s graphical experience or the integrated command-line experience provided by Cloud Shell. Get an overview, and see which Azure services can be managed with the Azure portal.','','TEXT_ONLY','Personalize your experience\nImagine a single easy-to-use console built just for you, your team, and your projects. This unified hub significantly simplifies building, deploying, and managing your cloud resources. Organize your portal to custom-fit your work and your work style. Stay on top of the things that matter most by pinning them to your dashboard. Resize tiles to show just the right amount of detail, and share insights across apps and resources.\n','https://ik.imagekit.io/genospark/middle_image_gwtYlcSeN7.jpg','LEFT_IMAGE_RIGHT_TEXT','Gain visibility with no more billing blind spots\nNow it’s easy to keep tabs on current and projected costs. The Azure portal automatically calculates your existing charges and forecasts your likely monthly charges—even if you’re managing hundreds of resources across several apps. Plus, it’s easy to see your cross-cloud analytics and real-time active use data when you enable monitoring and diagnostics and monitor service metrics, which helps you avoid billing surprises.\nGet integrated support when and where you need it\nWhether you need support because of an alert notification or you notice issues when you view events and audit logs, help is only a click away. Microsoft provides the full range of resources to help you get started and grow, including access to our communities and forums, specific troubleshooting information, and direct support from a world-class Azure support representative. Plus, you have access to a direct feedback channel for the Azure product team.','','TEXT_ONLY','Azure Features','','Azure, Mobile App, Accessibility','','','PUBLISHED',1,1,'Chandrashu Kumar',4,'2025-10-13 15:45:32',4,'2025-10-13 16:49:51',10);
/*!40000 ALTER TABLE `blog_posts` ENABLE KEYS */;
UNLOCK TABLES;

