  `certification_description` text COLLATE utf8mb4_general_ci,
  `certification_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `certificate_short_description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `certification_image_path` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `certification_level` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `domain_distribution` text COLLATE utf8mb4_general_ci,
  `is_future` tinyint(1) DEFAULT '0',
  `future_percent` float DEFAULT '0',
  `number_of_mock_questions` int DEFAULT '0',
  `number_of_practice_questions` int DEFAULT '0',
  `number_of_final_questions` int DEFAULT '0',
  `duration_mock` int DEFAULT '0',
  `duration_practice` int DEFAULT '0',
  `duration_final` int DEFAULT '0',
  `status_active` enum('active','inactive') COLLATE utf8mb4_general_ci DEFAULT 'inactive',
  `active_date` datetime DEFAULT NULL,
  `inactive_date` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `number_of_mock_tests` int DEFAULT '0' COMMENT 'Count of mock tests within this certification (always free)',
