  `final_exam_price` decimal(10,2) DEFAULT '0.00' COMMENT 'Price of final exam in INR',
  `bundle_price` decimal(10,2) DEFAULT '0.00' COMMENT 'Discounted price if user buys multiple tests within this certification',
  `certification_voucher_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Optional coupon code for discounts or promotions',
  `avg_minutes_per_question` float DEFAULT '2' COMMENT 'Average minutes per question for this certification, used to calculate custom test duration',
  PRIMARY KEY (`certification_id`),
