INSERT INTO `certification` VALUES (1,1,'AWS Certified Solutions Architect – Associate (SAA-C03)','SAA-C03','{\r\n  \"overview\": \"The AWS Certified Solutions Architect – Associate certification is intended for individuals with one or more years of hands-on experience designing distributed applications and systems on AWS. It validates the ability to architect and deploy secure and robust applications on AWS technologies using best practices.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"SAA-C03\",\r\n    \"level\": \"Associate\",\r\n    \"duration_minutes\": 130,\r\n    \"total_questions\": 65,\r\n    \"scored_questions\": 50,\r\n    \"passing_score\": 720,\r\n    \"fee_usd\": 150,\r\n    \"delivery_method\": \"Pearson VUE / PSI (test center or online proctored)\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Korean\", \"Simplified Chinese\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"IT professionals and cloud engineers with hands-on AWS experience\",\r\n    \"System architects and developers involved in designing cloud-native solutions\",\r\n    \"Anyone aiming to validate their knowledge of designing scalable, secure, and cost-effective AWS architectures\",\r\n    \"Those seeking career advancement as AWS-certified architects\"\r\n  ]\r\n}','Associate-level AWS architecture design certification (SAA-C03)','AWS cloud architecture and deployment certification','https://ik.imagekit.io/genospark/saa_co3_G0flIA00w.png','Associate','[\r\n  {\r\n    \"domain\": \"Design Secure Architectures\",\r\n    \"weight\": 30,\r\n    \"key_topics\": [\r\n      \"Implement IAM policies and permission boundaries\",\r\n      \"Protect data at rest and in transit\",\r\n      \"Secure application tiers and network layers\",\r\n      \"Use AWS services like KMS, IAM, SCPs, Secrets Manager\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Design Resilient Architectures\",\r\n    \"weight\": 26,\r\n    \"key_topics\": [\r\n      \"Design multi-AZ and multi-region architectures\",\r\n      \"Implement health checks, failover, and load balancing\",\r\n      \"Use services like Auto Scaling, Route 53, ELB\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Design High-Performing Architectures\",\r\n    \"weight\": 24,\r\n    \"key_topics\": [\r\n      \"Choose optimal compute solutions (EC2, Lambda, Fargate)\",\r\n      \"Select proper storage tiers (S3, EFS, FSx)\",\r\n      \"Design high-throughput and low-latency networking\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Design Cost-Optimized Architectures\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Use AWS pricing models to reduce costs\",\r\n      \"Right-size resources and use Compute Savings Plans\",\r\n      \"Monitor usage with AWS Budgets and Cost Explorer\"\r\n    ]\r\n  }\r\n]',1,0,20,65,65,20,130,130,'active','2025-09-29 11:37:45',NULL,1,1,'2025-09-29 11:37:45','2025-10-19 10:36:52',0,0,0,0.00,0.00,0.00,0.00,NULL,2),(10,5,'Databricks Certified Data Engineer Associate','DB-DEA-101','{\r\n  \"overview\": \"The Databricks Certified Data Engineer Associate certification validates an individual\'s ability to perform foundational data engineering tasks using the Databricks Data Intelligence Platform. This includes understanding the Databricks workspace and architecture, performing ETL (Extract, Transform, Load) operations using Apache Spark SQL or PySpark, and orchestrating workloads with Databricks Workflows. Successful candidates can efficiently ingest, transform, and manage data pipelines in production environments using Databricks and its integrated tools.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"Data Engineer Associate\",\r\n    \"level\": \"Associate\",\r\n    \"duration_minutes\": 90,\r\n    \"total_questions\": 45,\r\n    \"passing_score\": \"Not specified\",\r\n    \"fee_usd\": 200,\r\n    \"delivery_method\": \"Online proctored\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Português BR\", \"Korean\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Aspiring or junior data engineers using Databricks for ETL and pipeline development\",\r\n    \"Developers looking to validate skills in Apache Spark SQL and PySpark on Databricks\",\r\n    \"Professionals working on data ingestion, transformation, and workflow automation\",\r\n    \"Individuals aiming to pursue the Databricks Data Engineer Professional certification\"\r\n  ]\r\n}','Associate-level Databricks data engineering certification','Databricks ETL and data pipeline certification','https://lmsimage.blob.core.windows.net/cmsimages/certification-thumbnails/databricks_databricks_certified_data_engineer_associate_banner.webp','Associate','[\r\n  {\r\n    \"domain\": \"Databricks Intelligence Platform\",\r\n    \"weight\": 10,\r\n    \"key_topics\": [\r\n      \"Understand the Databricks workspace, architecture, and environment\",\r\n      \"Explain the Databricks Lakehouse and Delta Lake fundamentals\",\r\n      \"Identify Databricks components and their roles (clusters, notebooks, jobs)\",\r\n      \"Understand how Databricks integrates with cloud storage and compute layers\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Development & Ingestion\",\r\n    \"weight\": 30,\r\n    \"key_topics\": [\r\n      \"Use Apache Spark SQL and PySpark for data ingestion and ETL\",\r\n      \"Connect and extract data from external sources (cloud storage, databases, APIs)\",\r\n      \"Implement ingestion pipelines with Auto Loader or standard reads\",\r\n      \"Manage schema inference, data formats (Parquet, JSON, CSV), and metadata\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Processing & Transformations\",\r\n    \"weight\": 31,\r\n    \"key_topics\": [\r\n      \"Apply Spark transformations: filtering, joining, grouping, aggregations\",\r\n      \"Use User-Defined Functions (UDFs) for complex processing\",\r\n      \"Manage semi-structured and structured data (JSON, Delta Tables)\",\r\n      \"Implement data cleaning, deduplication, and type conversions\",\r\n      \"Leverage caching and partitioning for performance optimization\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Productionizing Data Pipelines\",\r\n    \"weight\": 18,\r\n    \"key_topics\": [\r\n      \"Configure and schedule Databricks Workflows for automated jobs\",\r\n      \"Build, deploy, and monitor production pipelines\",\r\n      \"Handle job dependencies, retries, and notifications\",\r\n      \"Implement incremental processing and CDC (Change Data Capture)\",\r\n      \"Use Delta Live Tables for pipeline orchestration and versioning\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Governance & Quality\",\r\n    \"weight\": 11,\r\n    \"key_topics\": [\r\n      \"Apply access control and permissions using Unity Catalog\",\r\n      \"Manage data lineage and audit trails\",\r\n      \"Ensure data quality through validations, expectations, and monitoring\",\r\n      \"Apply compliance best practices for secure data handling\"\r\n    ]\r\n  }\r\n]',0,68,20,30,51,60,90,120,'active','2025-10-07 12:49:26',NULL,1,1,'2025-10-07 12:49:26','2025-11-13 12:32:44',5,6,1,20.50,30.00,50.00,40.00,'GENSPK50',2),(11,6,'Oracle Database SQL Certified Associate (1Z0-071)','1Z0-071','{\r\n  \"overview\": \"The Oracle Database SQL Certified Associate certification verifies essential knowledge and skills in SQL and Oracle database concepts. It targets developers, database administrators, and IT professionals who want to prove their ability to create and manage Oracle databases using SQL. This certification provides a strong foundation in SQL querying, data manipulation, and control within Oracle Database environments.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"1Z0-071\",\r\n    \"level\": \"Associate\",\r\n    \"duration_minutes\": 120,\r\n    \"total_questions\": 63,\r\n    \"passing_score\": \"63%\",\r\n    \"fee_usd\": 245,\r\n    \"delivery_method\": \"Online proctored or onsite at Pearson VUE\",\r\n    \"languages\": [\"English\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Individuals seeking to validate their SQL skills\",\r\n    \"Database administrators and developers working with Oracle databases\",\r\n    \"Professionals aiming to pursue advanced Oracle certifications\",\r\n    \"Those interested in enhancing their data management capabilities\"\r\n  ]\r\n}','Associate-level Oracle SQL database certification','Oracle database SQL fundamentals certification','https://lmsimage.blob.core.windows.net/cmsimages/certification-thumbnails/oracle_oracle_database_sql_certified_associate__1z0_071__banner.webp','Associate','[\r\n  {\r\n    \"domain\": \"SQL Fundamentals\",\r\n    \"weight\": 30,\r\n    \"key_topics\": [\r\n      \"Understanding SQL syntax and structure\",\r\n      \"Creating and managing database objects\",\r\n      \"Implementing data types and constraints\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Retrieval and Manipulation\",\r\n    \"weight\": 30,\r\n    \"key_topics\": [\r\n      \"Writing SELECT statements\",\r\n      \"Using aggregate functions\",\r\n      \"Implementing joins and subqueries\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Definition\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Creating and modifying tables\",\r\n      \"Implementing indexes and views\",\r\n      \"Managing schemas and sequences\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Control\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Managing user privileges\",\r\n      \"Implementing roles and profiles\",\r\n      \"Auditing and securing data\"\r\n    ]\r\n  }\r\n]',0,0,25,35,40,60,90,120,'active','2025-10-07 13:21:16',NULL,1,1,'2025-10-07 13:21:16','2025-11-13 12:29:09',1,1,1,0.00,99.00,99.00,159.00,NULL,2),(14,1,'AWS Cloud Practitioner Certification (CLF-C02)','CLF-C02','{\r\n  \"overview\": \"The AWS Certified Cloud Practitioner is a foundational-level certification designed for individuals who are new to the cloud and AWS. It validates a basic understanding of AWS Cloud concepts, services, billing, security, and support models. Ideal for students, non-technical professionals, or early-stage cloud learners.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"CLF-C02\",\r\n    \"level\": \"Foundational\",\r\n    \"duration_minutes\": 90,\r\n    \"total_questions\": 65,\r\n    \"scored_questions\": 55,\r\n    \"passing_score\": 700,\r\n    \"fee_usd\": 100,\r\n    \"delivery_method\": \"Pearson VUE or PSI – online proctored or test center\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Korean\", \"Simplified Chinese\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Beginners to Cloud and AWS\",\r\n    \"Non-technical roles (Sales, Marketing, Finance)\",\r\n    \"Students and academic participants\",\r\n    \"Project managers and product owners interacting with cloud teams\"\r\n  ]\r\n}','Foundational AWS cloud concepts certification','Entry-level AWS cloud fundamentals certification','https://ik.imagekit.io/genospark/clf_co2_FXSCG_aov5.png','Foundational','[\r\n  {\r\n    \"domain\": \"Cloud Concepts\",\r\n    \"weight\": 24,\r\n    \"key_topics\": [\r\n      \"Benefits of Cloud (Agility, Cost savings, Elasticity)\",\r\n      \"Cloud deployment models: Public, Private, Hybrid\",\r\n      \"AWS Global Infrastructure: Regions, AZs, Edge Locations\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Security and Compliance\",\r\n    \"weight\": 30,\r\n    \"key_topics\": [\r\n      \"AWS Shared Responsibility Model\",\r\n      \"Identity and Access Management (IAM)\",\r\n      \"Multi-Factor Authentication (MFA)\",\r\n      \"AWS Organizations, Service Control Policies (SCP)\",\r\n      \"AWS Compliance Programs and AWS Artifact\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"AWS Technology (Core Services)\",\r\n    \"weight\": 34,\r\n    \"key_topics\": [\r\n      \"Compute: EC2, Lambda, Elastic Beanstalk, ECS\",\r\n      \"Storage: S3, EBS, EFS, Glacier\",\r\n      \"Networking: VPC, Route 53, ELB, CloudFront\",\r\n      \"Databases: RDS, DynamoDB\",\r\n      \"Monitoring: CloudWatch, CloudTrail\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Billing and Pricing\",\r\n    \"weight\": 12,\r\n    \"key_topics\": [\r\n      \"AWS Free Tier\",\r\n      \"Cost Explorer, AWS Budgets, Billing Alerts\",\r\n      \"Consolidated Billing\",\r\n      \"AWS Support Plans (Basic, Developer, Business, Enterprise)\"\r\n    ]\r\n  }\r\n]',1,0,10,65,65,20,130,130,'active',NULL,NULL,2,1,'2025-10-17 13:44:15','2025-11-03 16:56:42',2,0,2,0.00,0.00,0.00,0.00,NULL,2),(15,1,'AWS Certified AI Practitioner – Foundational Level (AIF-C01)','AIF-C01','{\r\n  \"overview\": \"The AWS Certified AI Practitioner certification is designed for individuals seeking foundational knowledge in AI and ML within the AWS ecosystem. It validates your ability to recognize use cases, understand AI/ML services, and communicate concepts effectively.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"AIF-C01\",\r\n    \"level\": \"Foundational\",\r\n    \"duration_minutes\": 90,\r\n    \"format\": [\"Multiple choice\", \"Multiple response\"],\r\n    \"total_questions\": 65,\r\n    \"scored_questions\": 50,\r\n    \"passing_score\": 700,\r\n    \"fee_usd\": 135,\r\n    \"delivery_method\": \"Pearson VUE / PSI\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Simplified Chinese\", \"Spanish\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Beginners in AI/ML\",\r\n    \"Business analysts, product managers, and early-career professionals\",\r\n    \"Technical students and educators\",\r\n    \"Cloud practitioners expanding into intelligent automation\"\r\n  ]\r\n}','Foundational AI/ML certification in AWS ecosystem','Introductory AWS AI/ML certification','https://ik.imagekit.io/genospark/alf_co1_-c6CznA6g.png','Foundational','[\r\n  {\r\n    \"domain\": \"AI & ML Fundamentals\",\r\n    \"weight\": 24,\r\n    \"key_topics\": [\r\n      \"AI vs ML\",\r\n      \"Types of ML\",\r\n      \"Deep learning basics\",\r\n      \"Supervised vs unsupervised learning\",\r\n      \"Difference between AI, ML, and DL\",\r\n      \"Dataset types and quality\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"AWS AI/ML Services & Tools\",\r\n    \"weight\": 32,\r\n    \"key_topics\": [\r\n      \"Amazon SageMaker (studio, training, deployment basics)\",\r\n      \"Amazon Rekognition (image/video analysis)\",\r\n      \"Amazon Comprehend (text analysis & NLP)\",\r\n      \"Amazon Lex (chatbot development)\",\r\n      \"Amazon Polly (text-to-speech)\",\r\n      \"Amazon Translate, Transcribe\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Use Cases & Responsible AI\",\r\n    \"weight\": 24,\r\n    \"key_topics\": [\r\n      \"Real-world AI applications (healthcare, finance, retail)\",\r\n      \"Bias detection, explainability, fairness\",\r\n      \"Privacy concerns, ethical frameworks\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"AI Integration in Applications\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Using AI in serverless/cloud-native apps\",\r\n      \"Calling AWS AI services via APIs\",\r\n      \"Data pipelines and integrations with business apps\"\r\n    ]\r\n  }\r\n]\r\n',1,0,10,20,5,90,120,180,'active',NULL,NULL,2,1,'2025-10-18 18:50:11','2025-10-19 10:37:14',0,0,0,0.00,0.00,0.00,0.00,NULL,2),(16,1,'AWS Certified Machine Learning Engineer – Associate (MLA-C01)','MLA-C01','{\r\n  \"overview\": \"The AWS Certified Machine Learning Engineer – Associate certification is designed for individuals who perform a development or data science role and have at least one year of hands-on experience developing, architecting, and maintaining ML or deep learning workloads on the AWS Cloud. This exam validates your ability to build, train, tune, and deploy ML models using the AWS Cloud.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"MLA-C01\",\r\n    \"level\": \"Associate\",\r\n    \"duration_minutes\": 170,\r\n    \"total_questions\": 65,\r\n    \"scored_questions\": 50,\r\n    \"passing_score\": 720,\r\n    \"fee_usd\": 150,\r\n    \"delivery_method\": \"Pearson VUE / PSI (testing center or online proctored)\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Korean\", \"Simplified Chinese\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Developers and data scientists with at least 1 year of experience in building ML solutions using AWS\",\r\n    \"Professionals aiming to specialize in ML workloads and pipeline automation\",\r\n    \"Candidates seeking to demonstrate practical skills in implementing, deploying, and monitoring ML models on AWS\",\r\n    \"Individuals with foundational AWS knowledge and a solid understanding of machine learning principles\"\r\n  ]\r\n}','Associate-level ML engineering certification for AWS','AWS ML model development and deployment certification','https://ik.imagekit.io/genospark/aws_certified_ml_associate_2_D5gb1qCxm.webp','Associate','[\r\n  {\r\n    \"domain\": \"Data Engineering\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Design and implement data ingestion and transformation pipelines\",\r\n      \"Choose appropriate AWS services for data processing\",\r\n      \"Perform feature engineering and feature selection\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Exploratory Data Analysis (EDA)\",\r\n    \"weight\": 24,\r\n    \"key_topics\": [\r\n      \"Handle missing and imbalanced data\",\r\n      \"Use statistics to summarize data characteristics\",\r\n      \"Apply visualization tools to understand data distribution\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Modeling\",\r\n    \"weight\": 36,\r\n    \"key_topics\": [\r\n      \"Select appropriate ML models based on task and data\",\r\n      \"Perform hyperparameter tuning\",\r\n      \"Evaluate model performance using metrics like F1, AUC, RMSE\",\r\n      \"Implement different training strategies (e.g., mini-batch, transfer learning)\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Machine Learning Implementation and Operations\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Deploy models using Amazon SageMaker endpoints\",\r\n      \"Monitor model performance and data drift\",\r\n      \"Automate pipelines with SageMaker Pipelines and MLOps best practices\",\r\n      \"Implement CI/CD practices for ML workflows\"\r\n    ]\r\n  }\r\n]',1,0,20,65,65,20,130,130,'active',NULL,NULL,4,1,'2025-10-19 08:28:25','2025-10-23 14:50:36',0,0,0,0.00,0.00,0.00,0.00,NULL,2),(17,1,'AWS Certified Data Engineer – Associate (DEA-C01)','DEA-C01','{\r\n  \"overview\": \"The AWS Certified Data Engineer – Associate certification is ideal for individuals who design, build, and maintain data pipelines on AWS. It tests your knowledge of data integration, transformation, storage, and analytics using AWS services and industry best practices.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"DEA-C01\",\r\n    \"level\": \"Associate\",\r\n    \"duration_minutes\": 170,\r\n    \"total_questions\": 65,\r\n    \"scored_questions\": 50,\r\n    \"passing_score\": 720,\r\n    \"fee_usd\": 150,\r\n    \"delivery_method\": \"Pearson VUE / PSI\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Korean\", \"Simplified Chinese\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Data engineers, analysts, and developers working with data pipelines\",\r\n    \"Professionals with hands-on experience using AWS services for ETL, warehousing, and analytics\",\r\n    \"Engineers transitioning into big data roles using cloud-based tools\",\r\n    \"Ideal for those looking to certify practical data workflow expertise in the AWS ecosystem\"\r\n  ]\r\n}','Associate-level data engineering certification for AWS','AWS data pipeline and analytics certification','https://lmsimage.blob.core.windows.net/cmsimages/certification-thumbnails/1761401537239_dea-c01.webp','Associate','[\r\n  {\r\n    \"domain\": \"Data Ingestion & Transformation\",\r\n    \"weight\": 34,\r\n    \"key_topics\": [\r\n      \"Implement batch and streaming pipelines\",\r\n      \"Use AWS Glue, Lambda, and DMS\",\r\n      \"Automate data transformation and error handling\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Storage & Data Management\",\r\n    \"weight\": 26,\r\n    \"key_topics\": [\r\n      \"Design data lakes and warehouses\",\r\n      \"Choose appropriate storage formats and tiers\",\r\n      \"Enforce access control and lifecycle policies\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Analysis & Visualization\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Query structured/unstructured data with Athena and Redshift\",\r\n      \"Build dashboards with QuickSight\",\r\n      \"Use EMR for distributed processing\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Security & Monitoring\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Apply encryption at rest/in transit\",\r\n      \"Monitor and audit data pipelines with CloudWatch and CloudTrail\",\r\n      \"Implement fine-grained IAM permissions and data masking\"\r\n    ]\r\n  }\r\n]',1,0,20,65,65,20,130,130,'active',NULL,NULL,4,1,'2025-10-19 08:35:22','2025-10-26 13:52:28',0,0,0,0.00,0.00,0.00,0.00,NULL,2),(18,1,'AWS Certified SysOps Administrator – Associate (SOA-C02)','SOA-C02','{\r\n  \"overview\": \"The AWS Certified SysOps Administrator – Associate is for system administrators responsible for managing AWS operations. It focuses on deployment, automation, monitoring, and cost control for AWS infrastructure.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"SOA-C02\",\r\n    \"level\": \"Associate\",\r\n    \"duration_minutes\": 180,\r\n    \"total_questions\": 65,\r\n    \"scored_questions\": 50,\r\n    \"passing_score\": 720,\r\n    \"fee_usd\": 150,\r\n    \"delivery_method\": \"Pearson VUE / PSI\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Korean\", \"Simplified Chinese\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"System administrators with AWS experience managing infrastructure\",\r\n    \"DevOps engineers seeking certification in operational excellence\",\r\n    \"Professionals responsible for monitoring, provisioning, and securing cloud environments\",\r\n    \"Ideal for those automating deployment and cost management tasks on AWS\"\r\n  ]\r\n}','Associate-level AWS operations administration certification','AWS infrastructure operations and management certification','https://ik.imagekit.io/genospark/aws_certified_sysops_admin_associate_HRlrVIzrv.webp','Associate','[\r\n  {\r\n    \"domain\": \"Monitoring, Reporting\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Use CloudWatch for custom metrics, alarms, and dashboards\",\r\n      \"Analyze performance data and set up alerts\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"High Availability, Backup\",\r\n    \"weight\": 16,\r\n    \"key_topics\": [\r\n      \"Design multi-AZ deployments and failover mechanisms\",\r\n      \"Automate snapshots and backups using AWS tools\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Deployment, Provisioning\",\r\n    \"weight\": 18,\r\n    \"key_topics\": [\r\n      \"Use CloudFormation templates for repeatable deployments\",\r\n      \"Integrate with Elastic Beanstalk and OpsWorks\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Storage, Compute, Network\",\r\n    \"weight\": 22,\r\n    \"key_topics\": [\r\n      \"Configure and maintain EC2, EBS, and S3\",\r\n      \"Manage VPC, NAT Gateway, route tables, subnets\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Security & Compliance\",\r\n    \"weight\": 16,\r\n    \"key_topics\": [\r\n      \"Enforce IAM policies, MFA, encryption using KMS\",\r\n      \"Monitor with AWS Config, CloudTrail\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Automation & Optimization\",\r\n    \"weight