am_details\": {\r\n    \"exam_code\": \"DP-900\",\r\n    \"level\": \"Beginner\",\r\n    \"duration_minutes\": 60,\r\n    \"total_questions\": \"40-60\",\r\n    \"passing_score\": 700,\r\n    \"fee_usd\": 99,\r\n    \"delivery_method\": \"Pearson VUE / Online proctored\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Korean\", \"Simplified Chinese\", \"and more\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Individuals new to working with data in the cloud\",\r\n    \"Professionals looking to validate foundational knowledge of data services in Azure\",\r\n    \"Those preparing for Azure data role-based certifications\"\r\n  ]\r\n}','Foundational Azure data services certification','Entry-level Azure data concepts certification','https://lmsimage.blob.core.windows.net/cmsimages/certification-thumbnails/azure_dp_900__microsoft_azure_data_fundamentals_banner.webp','Foundational','[\r\n  {\r\n    \"domain\": \"Describe core data concepts\",\r\n    \"weight\": 17.5,\r\n    \"key_topics\": [\r\n      \"Describe types of core data workloads\",\r\n      \"Describe data analytics core concepts\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Describe how to work with relational data on Azure\",\r\n    \"weight\": 27.5,\r\n    \"key_topics\": [\r\n      \"Describe relational data workloads\",\r\n      \"Describe relational Azure data services\",\r\n      \"Describe basic management tasks for relational data\",\r\n      \"Describe query techniques for data using SQL language\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Describe how to work with non-relational data on Azure\",\r\n    \"weight\": 27.5,\r\n    \"key_topics\": [\r\n      \"Describe non-relational data workloads\",\r\n      \"Describe non-relational data offerings on Azure\",\r\n      \"Describe basic management tasks for non-relational data\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Describe an analytics workload on Azure\",\r\n    \"weight\": 27.5,\r\n    \"key_topics