]',0,0,20,65,65,20,130,130,'active',NULL,NULL,4,4,'2025-10-28 09:52:19','2025-10-28 09:52:19',0,0,0,0.00,0.00,0.00,0.00,NULL,2),(26,2,'Microsoft Certified: Power BI Data Analyst Associate (PL-300)','PL-300','{\r\n  \"overview\": \"The PL-300 certification validates the ability to deliver actionable insights through data analysis and visualization using Microsoft Power BI. It is designed for business analysts and data professionals responsible for data analysis and visualization.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"PL-300\",\r\n    \"level\": \"Associate\",\r\n    \"duration_minutes\": 120,\r\n    \"total_questions\": \"40-60\",\r\n    \"passing_score\": 700,\r\n    \"fee_usd\": 165,\r\n    \"delivery_method\": \"Pearson VUE / Online proctored\",\r\n    \"languages\": [\"English\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Business analysts and data professionals responsible for data analysis and visualization\",\r\n    \"Individuals proficient in Power BI and DAX\",\r\n    \"Professionals aiming to deliver actionable insights through data visualizations\"\r\n  ]\r\n}','Associate-level Power BI data analyst certification','Power BI data analysis and visualization certification','https://lmsimage.blob.core.windows.net/cmsimages/certification-thumbnails/azure_microsoft_certified__power_bi_data_analyst_associate__pl_300__banner.webp','Associate','[\r\n  {\r\n    \"domain\": \"Prepare the data\",\r\n    \"weight\": 27.5,\r\n    \"key_topics\": [\r\n      \"Identify and connect to data sources\",\r\n      \"Clean, transform, and load data using Power Query\",\r\n      \"Profile data and resolve data quality issues\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Model the data\",\r\n    \"weight\": 27.5,\r\n    \"key_topics\": [\r\n      \"Design and create a data model\",\r\n      \"Define and create measures using DAX\",\r\n      \"Optimize model performance\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Visualize and analyze the data\",\r\n    \"weight\": 27.5,\r\n    \"key_topics\": [\r\n      \"Create reports and dashboards\",\r\n      \"Enhance reports for usability and storytelling\",\r\n      \"Perform advanced analysis\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Manage and secure Power BI assets\",\r\n    \"weight\": 17.5,\r\n    \"key_topics\": [\r\n      \"Manage datasets and workspaces\",\r\n      \"Implement row-level security\",\r\n      \"Configure data refresh and sharing settings\"\r\n    ]\r\n  }\r\n]',0,0,20,65,65,20,130,130,'active',NULL,NULL,4,4,'2025-10-28 09:55:05','2025-10-28 09:55:05',0,0,0,0.00,0.00,0.00,0.00,NULL,2),(27,2,'AZ-305: Microsoft Azure Solutions Architect Expert','AZ-305','{\r\n  \"overview\": \"AZ-305 validates advanced proficiency in designing and implementing cloud and hybrid solutions on Microsoft Azure. It is intended for professionals who can translate business needs into architectural designs aligned with Azure best practices.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"AZ-305\",\r\n    \"level\": \"Expert\",\r\n    \"duration_minutes\": 180,\r\n    \"total_questions\": \"40-60\",\r\n    \"passing_score\": 700,\r\n    \"fee_usd\": 165,\r\n    \"delivery_method\": \"Pearson VUE / Online-proctored\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Korean\", \"Simplified Chinese\", \"German\", \"Spanish\", \"French\", \"and more\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Experienced IT professionals who design cloud or hybrid system solutions\",\r\n    \"Candidates capable of aligning business needs with scalable Azure architectures\",\r\n    \"Professionals with strong knowledge in administration, development, networking, security, and governance\"\r\n  ]\r\n}','Expert-level Azure solutions architecture certification','Advanced Azure architecture design certification','https://lmsimage.blob.core.windows.net/cmsimages/certification-thumbnails/azure_az_305__microsoft_azure_solutions_architect_expert_banner.webp','Professional','[\r\n  {\r\n    \"domain\": \"Design identity, governance & monitoring solutions\",\r\n    \"weight\": 27.5,\r\n    \"key_topics\": [\r\n      \"Design authentication, authorization, and identity strategies (e.g. Azure AD, managed identities)\",\r\n      \"Design governance models (policies, blueprints, resource consistency)\",\r\n      \"Design monitoring, logging, and alerting frameworks across resources\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Design data storage solutions\",\r\n    \"weight\": 22.5,\r\n    \"key_topics\": [\r\n      \"Choose appropriate relational and non-relational storage (Azure SQL, Cosmos DB, Blob, etc.)\",\r\n      \"Plan for data partitioning, scaling, replication, and encryption\",\r\n      \"Define access patterns, performance, and consistency models\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Design business continuity solutions\",\r\n    \"weight\": 17.5,\r\n    \"key_topics\": [\r\n      \"Architect high availability and disaster recovery (e.g. zones, paired regions, failover)\",\r\n      \"Design backup and restore strategies for VMs, databases, and storage\",\r\n      \"Plan for site recovery and continuity across services\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Design infrastructure solutions\",\r\n    \"weight\": 32.5,\r\n    \"key_topics\": [\r\n      \"Network architectures: VNets, subnets, routing, firewall, load balancing\",\r\n      \"Compute strategy: VMs, containers, App Services, Azure Functions\",\r\n      \"Hybrid connectivity options: VPN, ExpressRoute, network integration\"\r\n    ]\r\n  }\r\n]',0,0,20,65,65,20,130,130,'active',NULL,NULL,4,4,'2025-10-28 10:00:28','2025-10-28 10:00:28',0,0,0,0.00,0.00,0.00,0.00,NULL,2),(28,4,'SnowPro Core Certification (COF-C02)','COF-C02','{\r\n  \"overview\": \"The SnowPro Core Certification (COF-C02) is designed to validate your foundational knowledge of the Snowflake AI Data Cloud. It tests your ability to design, manage, and optimize Snowflake environments — including data loading, transformation, performance tuning, and secure data sharing. Ideal for data engineers, analysts, architects, and administrators, this exam is the first step toward advanced SnowPro certifications.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"COF-C02\",\r\n    \"level\": \"Core / Associate\",\r\n    \"duration_minutes\": 115,\r\n    \"total_questions\": 100,\r\n    \"passing_score\": \"750+ (Scaled 0-1000)\",\r\n    \"fee_usd\": 175,\r\n    \"fee_india_usd\": 140,\r\n    \"delivery_method\": \"Online Proctored / Onsite Testing Centers\",\r\n    \"languages\": [\"English\", \"Japanese\", \"Korean\", \"French\", \"Spanish\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Data engineers, analysts, architects, and DBAs using Snowflake\",\r\n    \"Professionals seeking to validate knowledge of Snowflake\'s AI Data Cloud\",\r\n    \"Those aiming for advanced SnowPro certifications (Data Engineer, Architect, Admin)\",\r\n    \"Teams adopting Snowflake in modern data stack implementations\"\r\n  ]\r\n}','Core-level Snowflake AI Data Cloud certification','Foundational Snowflake data platform certification','https://lmsimage.blob.core.windows.net/cmsimages/certification-thumbnails/snowflake_snowpro_core_certification__cof_c02__banner.webp','Core','[\r\n  {\r\n    \"domain\": \"Snowflake AI Data Cloud Features & Architecture\",\r\n    \"weight\": 24,\r\n    \"key_topics\": [\r\n      \"Understand compute, storage, and cloud service layers\",\r\n      \"Explore virtual warehouses, scaling, caching, and regions\",\r\n      \"Work with data lake integration and cross-cloud connectivity\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Account Access and Security\",\r\n    \"weight\": 18,\r\n    \"key_topics\": [\r\n      \"Manage access with roles, grants, and policies\",\r\n      \"Configure network policies, MFA, and SSO\",\r\n      \"Secure access via key pair authentication or federated identity\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Performance and Cost Optimization Concepts\",\r\n    \"weight\": 16,\r\n    \"key_topics\": [\r\n      \"Understand query profile and caching layers\",\r\n      \"Apply clustering and micro-partitioning concepts\",\r\n      \"Implement warehouse auto-suspend/resume for cost efficiency\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Loading and Unloading\",\r\n    \"weight\": 12,\r\n    \"key_topics\": [\r\n      \"Use COPY INTO, stages (internal/external), and file formats\",\r\n      \"Load from AWS S3, Azure Blob, or GCP storage\",\r\n      \"Unload data for sharing or backup with efficiency\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Transformations\",\r\n    \"weight\": 18,\r\n    \"key_topics\": [\r\n      \"Design SQL pipelines using streams and tasks\",\r\n      \"Manage transformation logic through views and materialized views\",\r\n      \"Implement Snowpipe for continuous ingestion\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Protection and Data Sharing\",\r\n    \"weight\": 12,\r\n    \"key_topics\": [\r\n      \"Use cloning for fast, zero-copy duplication\",\r\n      \"Apply Time Travel and Fail-safe for recovery\",\r\n      \"Implement data sharing and data marketplace securely\"\r\n    ]\r\n  }\r\n]',0,0,20,65,65,20,130,130,'active','2025-10-28 20:16:23',NULL,1,1,'2025-10-28 20:16:23','2025-10-29 13:28:38',0,0,0,0.00,0.00,0.00,0.00,NULL,2),(29,3,'Google Cloud Certified: Cloud Digital Leader (GCP-CDL)','GCP-CDL','{\r\n  \"overview\": \"The Google Cloud Digital Leader certification validates foundational knowledge of cloud concepts and Google Cloud services. It is designed for business professionals, IT decision-makers, and those beginning their cloud journey who want to understand how Google Cloud can support digital transformation and innovation. This certification emphasizes understanding cloud concepts from a non-technical perspective and bridges business needs with cloud technology.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"GCP-CDL\",\r\n    \"level\": \"Foundational\",\r\n    \"duration_minutes\": 90,\r\n    \"total_questions\": \"50-60\",\r\n    \"passing_score\": \"Pass/Fail (Approx. 70%)\",\r\n    \"fee_usd\": 99,\r\n    \"delivery_method\": \"Online proctored or onsite at Pearson VUE\",\r\n    \"languages\": [\"English\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Business professionals seeking to understand cloud concepts\",\r\n    \"IT professionals exploring Google Cloud services\",\r\n    \"Consultants and project managers involved in cloud transformation\",\r\n    \"Individuals aiming to bridge the gap between business and technology\"\r\n  ]\r\n}','Foundational Google Cloud business and technology certification','Entry-level Google Cloud digital transformation certification','https://lmsimage.blob.core.windows.net/cmsimages/certification-thumbnails/gcp_google_cloud_certified__cloud_digital_leader__gcp_cdl__banner.webp','Foundational','[\r\n  {\r\n    \"domain\": \"Digital Transformation with Google Cloud\",\r\n    \"weight\": 12.5,\r\n    \"key_topics\": [\r\n      \"Understanding cloud business value\",\r\n      \"Identifying cloud adoption strategies\",\r\n      \"Recognizing industry-specific use cases\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Innovating with Data and Google Cloud\",\r\n    \"weight\": 32.5,\r\n    \"key_topics\": [\r\n      \"Utilizing BigQuery for data analytics\",\r\n      \"Implementing AI/ML solutions using Vertex AI\",\r\n      \"Leveraging data storage options like Cloud Storage and Spanner\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Infrastructure and Application Modernization\",\r\n    \"weight\": 32.5,\r\n    \"key_topics\": [\r\n      \"Migrating workloads to Google Cloud\",\r\n      \"Modernizing applications using Kubernetes Engine and App Engine\",\r\n      \"Implementing DevOps practices with Cloud Build and Cloud Deploy\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Understanding Google Cloud Security and Operations\",\r\n    \"weight\": 22.5,\r\n    \"key_topics\": [\r\n      \"Managing identity and access with IAM\",\r\n      \"Ensuring compliance and governance\",\r\n      \"Monitoring and logging with Operations Suite\"\r\n    ]\r\n  }\r\n]',0,0,20,65,65,20,130,130,'active',NULL,NULL,4,1,'2025-10-29 13:25:23','2025-11-11 14:15:13',3,0,0,0.00,0.00,0.00,0.00,NULL,2),(30,5,'Databricks Certified Data Analyst Associate','DB-DAA','{\r\n  \"overview\": \"The Databricks Certified Data Analyst Associate certification validates a candidate\'s ability to analyze data efficiently using the Databricks Data Intelligence Platform. It assesses practical skills in managing, querying, and analyzing data using Databricks SQL, Unity Catalog, and Databricks Dashboards, as well as the ability to utilize AI/BI Genie spaces for collaborative insights. Certified individuals can confidently work with data ingestion, transformation, visualization, and analysis tasks within Databricks, ensuring secure and optimized data operations.\",\r\n  \"exam_details\": {\r\n    \"exam_code\": \"Data Analyst Associate\",\r\n    \"level\": \"Associate\",\r\n    \"duration_minutes\": 90,\r\n    \"total_questions\": 45,\r\n    \"passing_score\": \"Not specified\",\r\n    \"fee_usd\": 200,\r\n    \"delivery_method\": \"Online proctored / Test center\",\r\n    \"languages\": [\"English\"],\r\n    \"negative_marking\": false\r\n  },\r\n  \"who_should_take\": [\r\n    \"Data Analysts and BI Professionals working in Databricks environments\",\r\n    \"SQL Analysts looking to validate their Databricks data querying and visualization skills\",\r\n    \"Data professionals managing datasets and dashboards within Unity Catalog\",\r\n    \"Individuals aiming to advance toward the Databricks Data Analyst Professional or Data Engineer track\"\r\n  ]\r\n}','Associate-level Databricks data analysis certification','Databricks SQL and analytics certification','https://lmsimage.blob.core.windows.net/cmsimages/certification-thumbnails/databricks_databricks_certified_data_analyst_associate_banner.webp','Associate','[\r\n  {\r\n    \"domain\": \"Understanding of Databricks Data Intelligence Platform\",\r\n    \"weight\": 11,\r\n    \"key_topics\": [\r\n      \"Identify key components of the Databricks Data Intelligence Platform\",\r\n      \"Understand the architecture, workspace, and data flow concepts\",\r\n      \"Recognize the role of Unity Catalog and Databricks SQL in data management\",\r\n      \"Describe key integrations for data discovery, analysis, and visualization\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Managing Data\",\r\n    \"weight\": 8,\r\n    \"key_topics\": [\r\n      \"Work with certified and registered datasets using Unity Catalog\",\r\n      \"Manage permissions, metadata, and data lineage\",\r\n      \"Discover, tag, and certify data assets for team usage\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Importing Data\",\r\n    \"weight\": 5,\r\n    \"key_topics\": [\r\n      \"Import and register datasets via UI, S3 ingestion, Delta Sharing, APIs, Auto Loader, and Marketplace\",\r\n      \"Understand different ingestion methods and their use cases\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Executing Queries using Databricks SQL & Warehouses\",\r\n    \"weight\": 20,\r\n    \"key_topics\": [\r\n      \"Create and execute SQL queries efficiently within Databricks SQL\",\r\n      \"Manage and configure SQL Warehouses\",\r\n      \"Perform joins, unions, subqueries, aggregations, and filters\",\r\n      \"Use temporary and permanent views for data exploration\",\r\n      \"Optimize query execution using caching and indexing techniques\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Analyzing Queries\",\r\n    \"weight\": 15,\r\n    \"key_topics\": [\r\n      \"Interpret query execution plans, history, and performance metrics\",\r\n      \"Audit query logs and usage reports\",\r\n      \"Use Liquid Clustering for performance tuning and data partitioning\",\r\n      \"Debug and optimize slow-running queries\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Creating Dashboards & Visualizations\",\r\n    \"weight\": 16,\r\n    \"key_topics\": [\r\n      \"Build interactive dashboards within Databricks SQL\",\r\n      \"Add visual elements (charts, KPIs, filters, etc.) to represent insights\",\r\n      \"Configure dashboard parameters, refresh schedules, and sharing options\",\r\n      \"Connect dashboards to live data sources\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Developing, Sharing & Maintaining AI/BI Genie Spaces\",\r\n    \"weight\": 12,\r\n    \"key_topics\": [\r\n      \"Understand AI/BI Genie space concepts for collaborative analytics\",\r\n      \"Create, maintain, and share analysis spaces securely\",\r\n      \"Develop simple models and insights using Genie\",\r\n      \"Apply best practices for managing workspace assets\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Data Modeling with Databricks SQL\",\r\n    \"weight\": 5,\r\n    \"key_topics\": [\r\n      \"Design logical data models using Databricks SQL\",\r\n      \"Implement relationships, primary keys, and joins\",\r\n      \"Create reusable data views for consistent reporting\"\r\n    ]\r\n  },\r\n  {\r\n    \"domain\": \"Securing Data\",\r\n    \"weight\": 8,\r\n    \"key_topics\": [\r\n      \"Apply best practices for access control, masking, and encryption\",\r\n      \"Manage user roles, table access, and auditing within Unity Catalog\",\r\n      \"Ensure compliance with organizational security policies\"\r\n    ]\r\n  }\r\n]',0,0,20,65,65,20,130,130,'inactive',NULL,NULL,4,1,'2025-10-29 13:34:52','2025-11-12 15:11:25',0,0,0,0.00,0.00,0.00,0.00,NULL,2);
