DROP TABLE IF EXISTS `certification_review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `certification_review` (
  `review_id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key for review',
  `certification_id` int NOT NULL COMMENT 'FK to certification',
  `provider_id` int NOT NULL COMMENT 'FK to provider',
  `user_id` int NOT NULL COMMENT 'FK to user who submitted the review',
  `review_type` enum('practice_test','final_test','practice_final') COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Type of review - practice test, final test, or both',
  `rating` tinyint NOT NULL COMMENT 'Star rating from 1 to 5',
  `review_comment` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'User feedback or experience comment',
  `improvement_suggested` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'Suggestions for improvement (optional)',
  `company_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Company or institution name of the reviewer',
  `user_role` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Role or designation of the reviewer',
  `status` enum('active','inactive') COLLATE utf8mb4_general_ci DEFAULT 'active' COMMENT 'Review status for moderation',
  `created_by` int DEFAULT NULL COMMENT 'User ID who created the record',
  `updated_by` int DEFAULT NULL COMMENT 'User ID who last updated the record',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Creation timestamp',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Last update timestamp',
  PRIMARY KEY (`review_id`),
  KEY `idx_cert_review_certification` (`certification_id`),
  KEY `idx_cert_review_provider` (`provider_id`),
  KEY `idx_cert_review_user` (`user_id`),
  KEY `idx_cert_review_type` (`review_type`),
  CONSTRAINT `fk_review_certification` FOREIGN KEY (`certification_id`) REFERENCES `certification` (`certification_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_review_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`provider_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_review_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Stores certification reviews for practice, final, or both tests with rating, feedback, and improvement suggestions';
/*!40101 SET character_set_client = @saved_cs_client */;

