  `meta_description` text,
  `tags` json DEFAULT NULL,
  `description` text,
  `image_url` varchar(500) DEFAULT NULL,
  `status` enum('DRAFT','PUBLISHED','UNPUBLISHED') DEFAULT 'DRAFT',
  `published_at` datetime DEFAULT NULL,
  `unpublished_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `has_sections` tinyint(1) NOT NULL DEFAULT '1',
  `use_common_footer` tinyint(1) NOT NULL DEFAULT '1',
  `use_common_header` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`page_id`),
