INSERT INTO `pages` VALUES (41,NULL,'New PRODUCTS Page','new-page-1759327615098','New PRODUCTS Page',NULL,'\"[]\"',NULL,NULL,'DRAFT',NULL,NULL,4,4,'2025-10-01 14:06:52','2025-10-01 14:10:45',1,1,1),(42,NULL,'About Genospark','about','About GenoSpark - Empowering Cloud Professionals | GenoSpark','Genospark Innovative Solutions is a forward-thinking EdTech and cloud consulting start-up dedicated to bridging the gap between academic knowledge and industry-ready skills.','\"[\\\"EdTech platform\\\",\\\"professional upskilling\\\",\\\"career advancement\\\",\\\"corporate training\\\",\\\"cloud professionals\\\",\\\"IT certification\\\",\\\"cloud computing courses\\\",\\\"cloud training\\\"]\"','Learn about GenoSpark\'s mission to empower aspiring individuals to secure high-paying careers in cloud computing and AI through practical training and certification programs.',NULL,'PUBLISHED','2025-10-25 11:06:51','2025-10-25 11:06:28',4,4,'2025-10-02 13:29:30','2025-10-25 11:06:50',1,1,1),(44,NULL,'Career Opportunities','careers','Career Opportunities - Join Our Team','Join our mission to empower the next generation of cloud professionals. Explore faculty positions, internships, and full stack developer opportunities.','\"[\\\"careers\\\",\\\"jobs\\\",\\\"internships\\\",\\\"faculty\\\",\\\"full stack developer\\\"]\"','Career opportunities at our organization',NULL,'PUBLISHED','2025-10-03 14:13:13',NULL,4,4,'2025-10-03 14:12:06','2025-10-27 15:39:00',1,1,1),(45,NULL,'Terms of Use','terms','Terms of Use - GenoSpark','Terms of Use for GenoSpark Innovative Solutions Pvt. Ltd. governing your access to and use of all our websites, platforms, applications, and educational services.','\"[\\\"terms\\\",\\\"legal\\\",\\\"policies\\\"]\"','Terms of Use page',NULL,'PUBLISHED','2025-10-05 09:14:08',NULL,4,4,'2025-10-05 09:13:52','2025-10-05 09:14:07',1,1,1),(46,NULL,'Refund Policy','refund-policy','Refund Policy - GenoSpark','GenoSpark Digital Purchase Refund Policy. 48-Hour Satisfaction Guarantee for Practice Tests and Near Real-Time Exam Simulators.','\"[\\\"refund\\\",\\\"policy\\\",\\\"legal\\\",\\\"purchase\\\"]\"','Refund Policy for GenoSpark digital products',NULL,'PUBLISHED','2025-10-05 15:12:05',NULL,4,4,'2025-10-05 15:11:58','2025-10-05 15:12:05',1,1,1),(47,NULL,'Privacy Policy','privacy-policy','Privacy Policy | GenoSpark - Data Protection & Privacy','Learn how GenoSpark Innovative Solutions Pvt. Ltd. collects, uses, and protects your personal information when you use our exam prep services and digital platforms.','\"[\\\"privacy policy\\\",\\\"data protection\\\",\\\"GDPR\\\",\\\"user privacy\\\",\\\"personal information\\\",\\\"GenoSpark\\\"]\"','Privacy Policy for GenoSpark Innovative Solutions Pvt. Ltd.',NULL,'PUBLISHED','2025-10-05 18:28:35',NULL,4,4,'2025-10-05 18:28:26','2025-10-05 18:28:35',1,1,1),(48,NULL,'Under Construction Page','under-construction','Under Construction Page',NULL,'\"[]\"','<section class=\"flex items-center justify-center px-6\" \n  style=\"min-height: 100vh; background-color: white;\">\n    <div class=\"text-center\" style=\"max-width: 28rem;\">\n\n      <svg class=\"mx-auto mb-6 animate-bounce\" style=\"width: 4rem; \n  height: 4rem; color: #eab308;\" fill=\"none\" stroke=\"currentColor\"        \n  viewBox=\"0 0 24 24\">\n        <path stroke-linecap=\"round\" stroke-linejoin=\"round\"\n  stroke-width=\"2\" d=\"M10.325 4.317c.426-1.756 2.924-1.756 3.35\n  0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724        \n  1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0        \n  00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572     \n  1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0\n  00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0\n  00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0\n  001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07\n  2.572-1.065z\" />\n        <path stroke-linecap=\"round\" stroke-linejoin=\"round\"\n  stroke-width=\"2\" d=\"M15 12a3 3 0 11-6 0 3 3 0 016 0z\" />\n      </svg>\n\n      <h1 style=\"font-size: 2.25rem; font-weight: 700; color: #111827;    \n   margin-bottom: 1rem;\">\n        Page Under Construction\n      </h1>\n\n      <p style=\"color: #4b5563; margin-bottom: 2rem;\">\n        We\'re working hard to bring you this page soon.\n        Please check back later or return to the homepage.\n      </p>\n\n      <div class=\"flex flex-col sm:flex-row gap-4 justify-center\">        \n        <a\n          href=\"/\"\n          class=\"flex items-center justify-center gap-2\"\n          style=\"background-color: #2563eb; color: white; padding:        \n  0.75rem 1.5rem; border-radius: 0.5rem; font-weight: 500; cursor:        \n  pointer; text-decoration: none;\"\n          onmouseover=\"this.style.backgroundColor=\'#1d4ed8\'\"\n          onmouseout=\"this.style.backgroundColor=\'#2563eb\'\"\n        >\n          <svg style=\"width: 1.25rem; height: 1.25rem;\" fill=\"none\"       \n  stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\"\n  stroke-width=\"2\" d=\"M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001\n  1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0\n  011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6\" />\n          </svg>\n          Back to Home\n        </a>\n        <a\n          href=\"/courses\"\n          style=\"padding: 0.75rem 1.5rem; border-radius: 0.5rem;\n  font-weight: 500; border: 1px solid #d1d5db; color: #1f2937; cursor:    \n   pointer; text-decoration: none; background-color: white;\"\n          onmouseover=\"this.style.backgroundColor=\'#f9fafb\'\"\n          onmouseout=\"this.style.backgroundColor=\'white\'\"\n        >\n          Browse Courses\n        </a>\n      </div>\n\n      <p style=\"font-size: 0.875rem; color: #6b7280; margin-top:\n  2rem;\">\n        🚧 This page is currently being built — thank you for your        \n  patience!\n      </p>\n    </div>\n  </section>',NULL,'PUBLISHED','2025-10-07 15:27:55',NULL,4,4,'2025-10-07 15:27:44','2025-10-07 15:37:19',0,1,1),(49,NULL,'CUSP++ — Advanced Data & Cloud Specialization','cusp2','CUSP++ | Genospark','CUSP++ is designed for students who have completed the CUSP program and want to specialize in Data Engineering, Data Analytics, Data Visualization, and AI/ML. This program focuses on real-world, hands-on projects and advanced cloud tools to prepare students for high-demand careers in data and AI.','\"[\\\"cusp++\\\",\\\"genospark cusp\\\",\\\"genospark cusp++\\\",\\\"cusp++ page\\\"]\"','CUSP++ is designed for students who have completed the CUSP program and want to specialize in Data Engineering, Data Analytics, Data Visualization, and AI/ML. This program focuses on real-world, hands-on projects and advanced cloud tools to prepare students for high-demand careers in data and AI.',NULL,'PUBLISHED','2025-10-23 17:25:25',NULL,2,2,'2025-10-23 17:10:03','2025-10-23 17:25:25',1,1,1),(50,NULL,'Collaborate with Us','collab-with-us','Collaborate with Us | GenoSpark','Explore partnership opportunities with GenoSpark. Collaborate with us on innovative projects and leverage our expertise in cloud computing and education.','\"[\\\"Collaboration\\\",\\\"Partnership\\\",\\\"GenoSpark\\\",\\\"Education Technology\\\",\\\"Business Collaboration\\\",\\\"Tech Partnership\\\",\\\"Innovation\\\"]\"','GenoSpark is always looking for partners to collaborate on exciting projects. Whether you\'re an individual expert, an educational institution, or a company, find out how we can work together to achieve mutual goals.',NULL,'PUBLISHED','2025-10-24 18:46:55',NULL,22,4,'2025-10-24 18:29:38','2025-10-25 17:41:01',1,1,1),(51,NULL,'Certification Training','certification-training','Professional Certification Training | GenoSpark','Accelerate your career with global cloud certifications. Final Exam Simulator, accelerated course content, and SAP program for individuals, universities, and businesses. Get certified faster with industry-recognized AWS, Azure, and GCP training.','\"[\\\"cloud certification\\\",\\\"exam simulator\\\",\\\"certification training\\\",\\\"SAP program\\\",\\\"university certification program\\\",\\\"corporate training\\\"]\"','{\n    \"component_type\": \"feature_tabs\",\n    \"tabs\": [\n      {\n        \"label\": \"Individual\",\n        \"title\": \"Accelerate Your Career with Global Certifications\",\n        \"bullets\": [\n          \"Final Exam Simulator – real exam environment to ensure\n  readiness\",\n          \"Accelerated Course Content – crisp notes for fast, effective\n  learning\",\n          \"SAP (Salary Augmentation Program) – certifications → better jobs     \n  → higher salaries\",\n          \"Certificates recognized worldwide\"\n        ],\n        \"button\": \"Start Learning\"\n      },\n      {\n        \"label\": \"For Universities\",\n        \"title\": \"Elevate Student Success & Campus Placements\",\n        \"bullets\": [\n          \"Final Exam Simulator – ensures students clear global\n  certifications with confidence\",\n          \"Accelerated Course Content – crisp notes for faster, effective       \n  learning\",\n          \"SAP (Salary Augmentation Program) – boost job offers & pay\n  packages\",\n          \"Augment campus hiring outcomes and attract top recruiters\",\n          \"Boost university reputation with industry-ready graduates\"\n        ],\n        \"button\": \"Start for Universities\"\n      },\n      {\n        \"label\": \"For Business\",\n        \"title\": \"Build Certified Cloud Teams That Drive Growth\",\n        \"bullets\": [\n          \"Final Exam Simulator – ensures employees pass certifications\n  confidently\",\n          \"Accelerated Content – save time with targeted knowledge\n  transfer\",\n          \"SAP Program – boost employee career paths, boost retention\",\n          \"Meet AWS/Azure/GCP partner certification requirements\",\n          \"Unlock partner funding, gain global client trust, and win\n  USA/Europe projects\"\n        ],\n        \"button\": \"Start for Business\"\n      },\n      {\n        \"label\": \"Cloud Talent\",\n        \"title\": \"Hire Certified Cloud Professionals, On Demand\",\n        \"bullets\": [\n          \"AWS / Azure / GCP certified engineers available immediately\",        \n          \"Cloud monitoring expertise (CloudWatch, Azure Monitor, GCP Ops)\",    \n          \"Cost-effective, project-ready professionals\",\n          \"Flexible engagement: short-term, long-term, or enterprise teams\",    \n          \"Backed by SAP and Final Exam Simulator → validated, job-ready        \n  talent\"\n        ],\n        \"button\": \"Hire Cloud Experts\"\n      }\n    ]\n  }',NULL,'DRAFT',NULL,NULL,4,4,'2025-10-25 10:55:19','2025-10-25 17:08:07',0,0,0);
