INSERT INTO `providers` VALUES (1,'AWS','Leading cloud services provider offering certifications at foundational, associate, professional, and specialty levels.','https://upload.wikimedia.org/wikipedia/commons/9/93/Amazon_Web_Services_Logo.svg','https://aws.amazon.com/certification/','Foundational,Associate,Professional,Specialty','active',1,NULL,'2025-09-29 11:37:45','2025-11-12 21:21:49'),(2,'Azure','Microsoft Azure cloud certification program covering fundamentals, associate, expert, and specialty levels.','https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Microsoft_Azure.svg/1920px-Microsoft_Azure.svg.png','https://learn.microsoft.com/en-us/certifications/','Fundamentals,Associate,Expert,Specialty','active',NULL,NULL,'2025-10-02 22:26:03','2025-11-13 12:36:53'),(3,'GCP','Google Cloud certification program offering foundational, associate, and professional levels.','https://icon.icepanel.io/Technology/svg/Google-Cloud.svg','https://cloud.google.com/learn/certification','Foundational,Associate,Professional','active',1,1,'2025-10-06 13:57:35','2025-11-12 21:21:49'),(4,'Snowflake','Snowflake Data Cloud certification program with core, advanced, and specialty levels for data professionals.','https://upload.wikimedia.org/wikipedia/commons/f/ff/Snowflake_Logo.svg','https://learn.snowflake.com/en/certifications/','Core,Advanced,Specialty','active',NULL,NULL,'2025-10-27 18:36:16','2025-11-12 21:21:49'),(5,'Databricks','Databricks certification framework with foundational, associate, and professional levels across data roles.','https://logos-world.net/wp-content/uploads/2024/01/Databricks-Emblem.png','https://www.databricks.com/learn/certification','Foundational,Associate,Professional','active',1,1,'2025-10-07 12:49:26','2025-11-12 21:21:49'),(6,'Oracle','Oracle certification framework offering multiple levels from foundations to master and specialist credentials.','https://upload.wikimedia.org/wikipedia/commons/5/50/Oracle_logo.svg','https://education.oracle.com/oracle-certification','Foundations,Associate,Professional,Expert,Master,Specialist','inactive',1,1,'2025-10-07 13:21:15','2025-11-12 21:21:49'),(7,'Microsoft','Microsoft is a technology company that offers a wide range of products and services.','//null','microsoft.com','One , Two, Three, Four, Five','active',NULL,NULL,'2025-11-11 17:22:33','2025-11-12 15:18:14');
