DROP TABLE IF EXISTS `salary_augment_applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `salary_augment_applications` (
  `application_id` int NOT NULL AUTO_INCREMENT,
  `full_name` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `email` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `contact_number` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `whatsapp_number` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `current_location` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `current_job_title` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `current_industry` enum('IT','Non-IT','Education','Healthcare','Finance','Manufacturing','Others') COLLATE utf8mb4_general_ci NOT NULL,
  `years_of_experience` enum('<1 year','1-3 years','3-5 years','5-10 years','10+ years') COLLATE utf8mb4_general_ci NOT NULL,
  `desired_career_path` enum('Cloud Computing','DevOps','Data Engineering','AI-ML','Others') COLLATE utf8mb4_general_ci NOT NULL,
  `target_cloud_platform` set('AWS','Azure','Google Cloud','Multi-Cloud') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `self_description` text COLLATE utf8mb4_general_ci NOT NULL,
  `preferred_contact_mode` enum('Email','Phone','WhatsApp') COLLATE utf8mb4_general_ci DEFAULT 'Email',
  `preferred_contact_time` enum('Morning','Afternoon','Evening') COLLATE utf8mb4_general_ci DEFAULT 'Afternoon',
  `linkedin_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `resume_file_path` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `application_status` enum('Submitted','In Review','Shortlisted','Rejected','Completed') COLLATE utf8mb4_general_ci DEFAULT 'Submitted',
  `created_by` varchar(100) COLLATE utf8mb4_general_ci DEFAULT 'System',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_by` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `is_active` tinyint(1) DEFAULT '1',
  `deleted_flag` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`application_id`),
  UNIQUE KEY `unique_email_contact` (`email`,`contact_number`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

