--
-- Table structure for table `sections`
--

DROP TABLE IF EXISTS `sections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sections` (
  `section_id` int NOT NULL AUTO_INCREMENT,
  `page_id` int NOT NULL,
  `section_type` enum('HERO','MIDDLE','SIDEBAR_LEFT','SIDEBAR_RIGHT','FOOTER','BANNER','BLOG_POST','FAQ_ITEM','LEGAL_ITEM') NOT NULL,
  `title` varchar(200) DEFAULT NULL,
  `content` longtext,
  `media_type` enum('IMAGE','VIDEO','PDF','CHEATSHEET','PPT','MOCK_TEST') DEFAULT NULL,
  `media_url` varchar(500) DEFAULT NULL,
  `file_id` int DEFAULT NULL,
  `display_order` int DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `active_date` datetime DEFAULT NULL,
  `inactive_date` datetime DEFAULT NULL,
  `published_date` datetime DEFAULT NULL,
  `unpublished_date` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`section_id`),
  KEY `fk_section_page` (`page_id`),
  KEY `fk_section_created_by` (`created_by`),
  KEY `fk_section_updated_by` (`updated_by`),
  CONSTRAINT `fk_section_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`user_id`),
  CONSTRAINT `fk_section_page` FOREIGN KEY (`page_id`) REFERENCES `pages` (`page_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_section_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

