--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `user_id` int NOT NULL AUTO_INCREMENT,
  `first_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `last_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `user_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_location` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_city` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_country` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `email` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `remember_me_token` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `failed_login_attempts` int DEFAULT '0',
  `is_locked` tinyint(1) DEFAULT '0',
  `last_login` datetime DEFAULT NULL,
  `role` enum('subscriber','instructor','admin') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status_active` enum('active','inactive') COLLATE utf8mb4_general_ci DEFAULT 'inactive',
  `active_date` datetime DEFAULT NULL,
  `inactive_date` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
